mapper.sql:
WHERE p.status = 'PUBLISHED'
  AND p.deleted_at IS NULL

    AND (
        p.title LIKE CONCAT('%', #{keyword}, '%')
        OR p.summary LIKE CONCAT('%', #{keyword}, '%')
        OR p.content LIKE CONCAT('%', #{keyword}, '%')
    )


    AND category.category_id = #{categoryId}


    AND rr.region = #{region}


    AND EXISTS (
        SELECT 1
          FROM post_tags pt
          JOIN tags t ON t.tag_id = pt.tag_id
         WHERE pt.post_id = p.post_id
           AND REPLACE(t.normalized_name, ' ', '') LIKE CONCAT('%', #{tag}, '%')
    )


    AND rr.distance_km >= #{minDistance}


    AND rr.distance_km <= #{maxDistance}
